const items = $input.all();
const products = items.map(item => item.json);
const analyzed = products.map(product => {
  const previousPrice = product.price * (1 + (Math.random() * 0.2 - 0.1));
  const change = product.price - previousPrice;
  const changePct = ((change / previousPrice) * 100).toFixed(2);
  return { id: product.id, name: product.title.substring(0, 50), category: product.category, currentPrice: product.price, previousPrice: previousPrice.toFixed(2), change: change.toFixed(2), changePct: changePct, direction: change > 0 ? '📈 UP' : change < 0 ? '📉 DOWN' : '➡️ SAME' };
});
const significant = analyzed.filter(p => Math.abs(parseFloat(p.changePct)) >= 5);
const increased = significant.filter(p => parseFloat(p.change) > 0);
const decreased = significant.filter(p => parseFloat(p.change) < 0);
return [{ json: { totalTracked: products.length, significantChanges: significant.length, increased: increased.length, decreased: decreased.length, topChanges: significant.slice(0, 5), runDate: new Date().toISOString().split('T')[0] } }];
